test('reviewable policy/test edits do not authorize changed or new privileged workflows', () => {
  const trusted = candidateWorkspace();
  const candidate = candidateWorkspace();
  const relativePath = '.github/workflows/other.yml';
  const workflow = {
    name: 'other',
    on: { workflow_dispatch: {} },
    permissions: { contents: 'read' },
    jobs: { check: { 'runs-on': 'ubuntu-latest', steps: [{ run: 'echo read-only' }] } },
  };
  try {
    for (const file of [
      'backend-deploy-workflow-policy.mjs',
      'backend-deploy-gate.test.mjs',
    ]) {
      fs.appendFileSync(path.join(candidate, '.github', 'scripts', file), '\n// reviewed edit\n');
    }
    const mutations = [
      ['write permission', (value) => { value.permissions.contents = 'write'; }],
      ['OIDC', (value) => { value.jobs.check.permissions = { 'id-token': 'write' }; }],
      ['secret', (value) => { value.jobs.check.steps[0].run = 'echo "${{ secrets.TOKEN }}"'; }],
      ['environment', (value) => { value.jobs.check.environment = 'prod'; }],
      ['CD', (value) => { value.jobs.check.steps[0].run = 'az functionapp deploy'; }],
    ];
    for (const existsInBase of [false, true]) {
      if (existsInBase) {
        fs.writeFileSync(path.join(trusted, ...relativePath.split('/')), YAML.stringify(workflow));
      }
      for (const [name, mutate] of mutations) {
        const changed = structuredClone(workflow);
        mutate(changed);
        fs.writeFileSync(path.join(candidate, ...relativePath.split('/')), YAML.stringify(changed));
        assert.match(
          validateBackendDeployWorkspace(candidate, trusted).join('\n'),
          /changed or new privileged capability is forbidden/u,
          `${existsInBase ? 'changed' : 'new'} ${name}`,
        );
      }
    }
  } finally {
    fs.rmSync(trusted, { force: true, recursive: true });
    fs.rmSync(candidate, { force: true, recursive: true });
  }
});

test('workspace rejects a symlink trust root and privileged shadow workflows', () => {
  const symlinkRoot = candidateWorkspace();
  const shadowRoot = candidateWorkspace();
  const quotedPermissionRoot = candidateWorkspace();
  const flowPermissionRoot = candidateWorkspace();
  const windowsPathRoot = candidateWorkspace();
  const mixedCaseAzureRoot = candidateWorkspace();
  const genericSecretRoot = candidateWorkspace();
  const external = path.join(symlinkRoot, 'external-policy');
  try {
    fs.mkdirSync(external);
    for (const relativePath of backendDeployTrustedFiles) {
      const control = path.join(symlinkRoot, ...relativePath.split('/'));
      fs.rmSync(control);
      fs.symlinkSync(external, control, 'junction');
      assert.match(
        validateBackendDeployWorkspace(symlinkRoot, repositoryRoot).join('\n'),
        /regular non-symlink file/u,
        relativePath,
      );
      fs.rmSync(control);
      copyFile(symlinkRoot, relativePath);
    }

    fs.copyFileSync(
      workflowPath,
      path.join(shadowRoot, '.github', 'workflows', 'cd-backend-shadow.yml'),
    );
    assert.match(
      validateBackendDeployWorkspace(shadowRoot, repositoryRoot).join('\n'),
      /changed or new privileged capability is forbidden/u,
    );

    for (const [root, permission] of [
      [quotedPermissionRoot, '"id-token": write'],
      [flowPermissionRoot, 'permissions: {"id-token": write}'],
    ]) {
      const shadowPath = path.join(
        root,
        '.github',
        'workflows',
        'quoted-shadow.yml',
      );
      const permissions = permission.startsWith('permissions:')
        ? `    ${permission}`
        : `    permissions:\n      ${permission}`;
      fs.writeFileSync(
        shadowPath,
        [
          'name: quoted-shadow',
          'on:',
          '  push:',
          'jobs:',
          '  privileged:',
          permissions,
          '    runs-on: ubuntu-latest',
          '    steps:',
          '      - run: echo privileged',
          '',
        ].join('\n'),
        'utf8',
      );
      assert.match(
        validateBackendDeployWorkspace(root, repositoryRoot).join('\n'),
        /changed or new privileged capability is forbidden/u,
      );
    }

    const windowsPathShadow = path.join(
      windowsPathRoot,
      '.github',
      'workflows',
      'windows-path-shadow.yml',
    );
    fs.writeFileSync(
      windowsPathShadow,
      [
        'name: windows-path-shadow',
        'on:',
        '  push:',
        'jobs:',
        '  build:',
        '    runs-on: windows-latest',
        '    steps:',
        '      - run: dotnet publish backend\\src\\Certigo.Api',
        '',
      ].join('\n'),
      'utf8',
    );
    assert.match(
      validateBackendDeployWorkspace(windowsPathRoot, repositoryRoot).join('\n'),
      /changed or new privileged capability is forbidden/u,
    );

    for (const [root, workflowText] of [
      [
        mixedCaseAzureRoot,
        [
          'name: mixed-case-azure-shadow',
          'on: push',
          'jobs:',
          '  deploy:',
          '    runs-on: ubuntu-latest',
          '    steps:',
          '      - uses: Azure/Login@0123456789012345678901234567890123456789',
        ].join('\n'),
      ],
      [
        genericSecretRoot,
        [
          'name: generic-secret-shadow',
          'on: push',
          'jobs:',
          '  leak:',
          '    runs-on: ubuntu-latest',
          '    steps:',
          "      - run: echo \"${{ secrets['AUTH_JWT_SIGNING_KEY'] }}\"",
        ].join('\n'),
      ],
    ]) {
      fs.writeFileSync(
        path.join(root, '.github', 'workflows', 'semantic-shadow.yml'),
        workflowText,
        'utf8',
      );
      assert.match(
        validateBackendDeployWorkspace(root, repositoryRoot).join('\n'),
        /changed or new privileged capability is forbidden/u,
      );
    }
  } finally {
    fs.rmSync(symlinkRoot, { force: true, recursive: true });
    fs.rmSync(shadowRoot, { force: true, recursive: true });
    fs.rmSync(quotedPermissionRoot, { force: true, recursive: true });
    fs.rmSync(flowPermissionRoot, { force: true, recursive: true });
    fs.rmSync(windowsPathRoot, { force: true, recursive: true });
    fs.rmSync(mixedCaseAzureRoot, { force: true, recursive: true });
    fs.rmSync(genericSecretRoot, { force: true, recursive: true });
  }
});

test('dispatch authorizer accepts the exact operation/environment allowlist', () => {
  for (const [operation, environment] of [
    ['release', 'dev'],
    ['promotion', 'staging'],
    ['promotion', 'prod'],
    ['rollback', 'dev'],
    ['rollback', 'staging'],
    ['rollback', 'prod'],
  ]) {
    const result = runDispatch({
      CLIENT_PAYLOAD_JSON: JSON.stringify({
        environment,
        operation,
        source_run_id: '1234',
      }),
    }, { name: environment });
    assert.equal(result.status, 0, result.stderr);
    assert.match(result.stdout, new RegExp(`environment=${environment}`, 'u'));
    assert.match(
      result.stdout,
      new RegExp(`source-run-id=${operation === 'release' ? '9001' : '1234'}`, 'u'),
    );
  }
});

test('dispatch authorizer rejects non-human, mismatched and unlisted actors', () => {
  for (const overrides of [
    { EVENT_SENDER_TYPE: 'Bot' },
    { EVENT_SENDER_TYPE: 'App' },
    { EVENT_ACTOR: '' },
    { EVENT_ACTOR: 'bob' },
    { AUTHORIZED_OPERATORS_JSON: '["bob"]' },
    { AUTHORIZED_OPERATORS_JSON: '["alice","alice"]' },
    { AUTHORIZED_OPERATORS_JSON: '["alice[bot]"]' },
  ]) {
    assert.notEqual(runDispatch(overrides).status, 0);
  }
});

test('dispatch authorizer rejects malformed, duplicate and noncanonical allowlists', () => {
  for (const allowlist of [
    '',
    '{',
    '{}',
    '[]',
    '["alice","alice"]',
    '[" alice"]',
    '["-alice"]',
    '["_leading"]',
    '["trailing_"]',
    '["a_b_c"]',
    '["a--b"]',
    '["alice[bot]"]',
    JSON.stringify(Array.from({ length: 51 }, (_, index) => `actor-${index}`)),
  ]) {
    assert.notEqual(
      runDispatch({ AUTHORIZED_OPERATORS_JSON: allowlist }).status,
      0,
      allowlist,
    );
  }
});

